const CjkFontTable* FindCjkFontTable(const char* theStem)
{
	if (theStem == nullptr)
		return nullptr;
	for (const CjkFontTable& aTable : kTables)
	{
		if (std::strcmp(aTable.mStem, theStem) == 0)
			return &aTable;
	}
	return nullptr;
}

